from pathlib import Path
import json,numpy as np
R=Path(__file__).resolve().parents[2];H=R/'research/round117';rd=lambda p:json.loads(Path(p).read_text())
def main():
 assert rd(H/'SCALAR_AUDIT.json')['n']==1536;aa=rd(H/'scores_attempt001/AGGREGATE_ROWS.json');rr=[r for f in (H/'scores_attempt001').glob('*_ALL_ROWS_PRIVATE.json') for r in rd(f)];p='repaired_fusedABC';controls=['native_fusedABC','real_BBF_fusedABC','repaired_ABC_mean','lateOnly_fusedABC','fixed_calibration_fusedABC'];conc=[];cases=[]
 for c in controls:
  d=np.array([r['arms'][p]['IoU']-r['arms'][c]['IoU'] for r in rr]);conc.append({'control':c,'n':len(d),'gain_pp':float(d.mean()*100),'better':int((d>1e-12).sum()),'worse':int((d< -1e-12).sum()),'same':int((abs(d)<=1e-12).sum()),'largest_positive_single_input_pp':float(max(0,d.max())*100/1536),'largest_negative_single_input_pp':float(min(0,d.min())*100/1536)})
  for name in rd(R/'crossplatform/round117/MATRIX_SEALED.json')['directions']:
   for label,sgn in [('good',1),('failure',-1)]:
    rs=[r for r in rr if r['source']+'_to_'+r['target']==name and not r['protected_alias_fallback'] and sgn*(r['arms'][p]['IoU']-r['arms'][c]['IoU'])>1e-12]
    if rs:
     r=max(rs,key=lambda r:abs(r['arms'][p]['IoU']-r['arms'][c]['IoU']));cases.append({'source':r['source'],'target':r['target'],'row_PRIVATE':r['id_PRIVATE'],'kind':label,'control':c,'delta_IoU':r['arms'][p]['IoU']-r['arms'][c]['IoU'],'postseal_only':True,'identity':'UNKNOWN_unless_visually_reviewed'})
 for n,x in [('CONCENTRATION_SUMMARY',conc),('GOOD_FAILURE_CASES_PRIVATE',cases)]: (H/(n+'.json')).write_text(json.dumps(x,indent=2)+'\n')
 lines=['# R117 — 固定原生基础修复的扩展验证','','本轮是冻结架构验证，不是R115逐输入gate配方的扩展TTA。沿用R109的1536定向输入/768表达，DEV元数据路径不重叠，但历史fullVAL/R109评分曝光，不是新独立测试。Waymo/Drone/Quad各256表达、两个incoming source；110保护媒体别名仅冻结prepared回退。FINAL未访问，source100/R91参数未重训，没有专家。','','## 固定配置和数据边界','','主项撤回point_adapter.up和earlyRGB gateP，保留原native点—文字基础、RGB桥/late和竞争残差；另做native纯匹配、rOnly、lateOnly以及同预算ABC概率平均。原source、原preparedA/F及旧CE池均直接复用。R115用无标签DEV梯度得到的source固定门均值及等范数反向，只是冻结校准对照，不在扩展输入重新拟合、不将其称为输入特定TTA。所有原A256/六层位置固定，不新增框。','','R109没有保存prefix和对齐PointNet向量，本轮只提取这些缺失前置表示，复用所有原注册/时间候选/支持阈值和sample哈希，不重新SIFT/PnP。实际旧preparedA/F隐藏态在12真实工程输入上位等，正式逐条核验原source概率、固定框、注册/采样/有效支持，与旧实验一致。当前A原生h/u与捕获原source位等。所有prefix/观测保存，后续无需再做这些前置提取。','','## 全体与平台','','| 范围 | 方法 | mIoU% | Acc25% | Acc50% |','|---|---|---:|---:|---:|']
 for x in aa:
  if x['group']=='all_six_equal' or x['arm'] in ['prepared_frozen','real_BBF_fusedABC','native_fusedABC','repaired_fusedABC','lateOnly_fusedABC','repaired_ABC_mean','fixed_calibration_fusedABC']:lines.append(f"| {x['group']} | {x['arm']} | {x['mIoU_percent']:.6f} | {x['Acc25_percent']:.6f} | {x['Acc50_percent']:.6f} |")
 lines+=['','## 裁决','','主修复16.314985%，高于preparedF16.238436与nativeF16.237263，但低于同信息ABC概率平均16.416137，固定主项未通过全部强对照。源域Point Adapter/earlyRGB的DEV撤回增益没有等幅保持，不能将其当普适已修复架构。固定门校准16.304593低于主修复16.314985，其DEV额外正收益同样未保留；不启动在线单门或域级校准TTA来挽救。','','组件消融最明确的是，保留RGB late而去掉竞争残差达到16.439770，rOnly16.205650反而低于nativeF16.237263。与DEV中r有正贡献不同，当前竞争残差在新观测上未带来总体增量。撤回原Point Adapter后，r头的输入也改变了；它可能是残差可靠性或训练输入条件失配，尚不能仅凭分数确定。R92的旧完整架构残差漂移阴性不排除这个新条件。所有较强次项保留，不切换主项或据平台GT拼接方案。','','## 完整正负尾部','','```json',json.dumps(conc,indent=2),'```','','独立样本和场景数量没有因两个source复制同一表达而翻倍；Waymo场景较多，Drone/Quad仍是少数原场景，不做跨新场景稳定性宣称。所有别名/不可用C/负例保留总分分母，IoU变化不自动认证实例身份。','','## 审计','','23读出共35328任务值，17新26112与6旧9216复用；24242新CPU端点，全部新任务值由两种几何实现核验，平台/场景/paired由独立代码重算。概率误差<5e-6、近平0。12工程后仅补保存已经计算的B基础以便独立CPU审计ABC均值，不改变推理或重跑NN；元数据修订留档。所有新预测先封存再评分。','','下一项只检验竞争头输入条件：在相同固定native基础上，比较原native特征读出的r、原source-compatible特征读出的r、无r及查询对应打乱。没有必要再开一轮GN层或Huber/MSE强度搜索。'];(H/'REPORT.md').write_text('\n'.join(lines)+'\n');print('REPORT117_COMPLETE',flush=True)
if __name__=='__main__':main()
